_LOGO: list[Image.Image | None] = [None]


def make_icon(size=256):
    """App logo (the manga-panel S badge); falls back to the old drawn logo if decoding fails."""
    try:
        im = _LOGO[0]
        if im is None:
            im = Image.open(io.BytesIO(base64.b64decode("".join(LOGO_B64)))).convert("RGBA")
            _LOGO[0] = im
        return im.copy() if size == im.width else im.resize((size, size), Image.Resampling.LANCZOS)
    except Exception:
        # last resort: a plain badge, so a broken logo image never stops the app
        im = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        d = ImageDraw.Draw(im)
        d.rounded_rectangle((0, 0, size - 1, size - 1), radius=size // 5, fill=(12, 13, 17, 255))
        try:
            d.text((size / 2, size / 2), "S", font=ImageFont.load_default(),
                   fill=(228, 232, 239, 255), anchor="mm")
        except Exception:
            pass
        return im


def make_icon_file(path):
    if not os.path.exists(path):
        make_icon(256).save(path, sizes=[(16, 16), (24, 24), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)])
